function on_complete(dst_reg_id, rob_tag, result_value, reg_type):
    if dst_reg_id < 65:
        if sR_RegTracker[dst_reg_id].payload == (rob_tag & 0x3FFF):
            digest = generate_digest(result_value, reg_type)
            sR_RegTracker[dst_reg_id].payload = digest & 0xFFF
            sR_RegTracker[dst_reg_id].valid = 1
            sR_RegTracker[dst_reg_id].decay_ctr = 255

function on_decode(dst_reg_id, rob_tag):
    if dst_reg_id < 65:
        sR_RegTracker[dst_reg_id].valid = 0
        sR_RegTracker[dst_reg_id].payload = rob_tag & 0x3FFF
        sR_RegTracker[dst_reg_id].decay_ctr = 255

function count_trailing_zeros_or_ones(val):
    bit = val & 1
    cnt = 0
    while cnt < 64 and ((val >> cnt) & 1) == bit:
        cnt = cnt + 1
    return cnt

function count_leading_zeros_or_ones(val):
    bit = (val >> 63) & 1
    cnt = 0
    while cnt < 64 and ((val >> (63 - cnt)) & 1) == bit:
        cnt = cnt + 1
    return cnt

function is_fp16(val):
    return (val >> 16) == 0

function is_fp32(val):
    return (val >> 32) == 0

function generate_digest(val, reg_type):
    if reg_type == INT:
        // 6-bit counts of trailing and leading identical bits, 6 LSBs of value
        trailing_cnt = count_trailing_zeros_or_ones(val) & 0x3F
        leading_cnt = count_leading_zeros_or_ones(val) & 0x3F
        lsb6 = val & 0x3F
        // 3-way XOR fold with 3-bit horizontal overlap offsets
        digest = trailing_cnt ^ (leading_cnt << 3) ^ (lsb6 << 6)
        return digest & 0xFFF
    else if reg_type == FP:
        // Inspect format: FP16 uses Val[15:13], FP32 uses Val[31:26], FP64 uses Val[63:55]
        if is_fp16(val):
            fp_res = (val[15:13] & 0x7) << 3
            return fp_res
        else if is_fp32(val):
            fp_res = (val[31:26] & 0x3F) << 3
            return fp_res
        else: // FP64
            fp_res = (val[63:55] & 0x1FF) << 3
            return fp_res
    else if reg_type == FLAGS:
        // 4-bit condition flags replicated 3 times into 12 bits
        flags4 = val & 0xF
        flags_res = flags4 | (flags4 << 4) | (flags4 << 8)
        return flags_res
    else:
        return 0
